  1	import { CONFIG } from '../../config';
  2	
  3	/* =====================================================================
  4	   DÁNG ĐI / DÁNG CHẠY NGƯỜI ĐI BỘ — bản CPU của shader trong material.ts (spec §5, G6, G7).
  5	   Shader mới là chỗ chạy thật; file này giữ cùng công thức để unit test kiểm (tests/people-unit/gait.test.ts)
  6	   và để code dựng tính nhịp bước (aVar.w) cho từng người. Đổi công thức ở đây thì sửa cả PP_GLSL_ANGLES trong material.ts.
  7	   Góc dương = đưa về phía trước (người hướng +X, quay quanh trục Z). φ là pha chu kỳ hai bước:
  8	   chân trái φ, chân phải φ + π, tay ngược pha chân cùng bên. Trộn đi ↔ chạy theo biên độ: run = smoothstep(0,42; 0,6; A).
  9	   ===================================================================== */
 10	export type PersonKind = 'walk' | 'run' | 'stand';
 11	export type PersonPart = 'legL' | 'legR' | 'armL' | 'armR';
 12	const P = CONFIG.people;
 13	
 14	const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
 15	const smoothstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
 16	/* Mức chạy 0..1 theo biên độ hông (đi 0,34 → 0, chạy 0,6 → 1) */
 17	export const ppRunMix = (amp: number) => smoothstep(0.42, 0.6, amp);
 18	/* Biên độ hông theo kiểu người */
 19	export const ppAmp = (kind: PersonKind) => (kind === 'walk' ? P.walk.amp : kind === 'run' ? P.run.amp : 0);
 20	
 21	/* Nhịp (rad/s của φ). Đi: chân trụ không trượt ⇔ ω · bước / 2π = v. Chạy: nhịp cố định, người nhỏ bước nhanh hơn. Đứng: 0 */
 22	export function ppCadence(kind: PersonKind, speed: number, scale: number): number {
 23	  if (kind === 'walk') return (2 * Math.PI * speed) / (4 * P.legLength * scale * Math.sin(P.walk.amp));
 24	  if (kind === 'run') return P.run.cadence / Math.sqrt(scale);
 25	  return 0;
 26	}
 27	
 28	/* Quãng đường một chu kỳ hai bước (m): mỗi bước chân trụ quét dây cung 2·L·sin A. Chạy ở tỉ lệ 1 ≈ 1,94 m, khớp 2,6–3,0 m/s ở 1,4 chu kỳ/giây */
 29	export function ppStride(kind: PersonKind, scale: number): number {
 30	  return kind === 'stand' ? 0 : 4 * P.legLength * scale * Math.sin(ppAmp(kind));
 31	}
 32	
 33	/* Góc khớp: root = hông / vai, joint = gối (≤ 0, gập về sau) / khuỷu (≥ 0, gập về trước). Không tính tư thế chụp ảnh (cờ 4, chỉ có trong shader). */
 34	export function ppAngles(part: PersonPart, amp: number, phase: number): { root: number; joint: number } {
 35	  const A = amp, run = ppRunMix(A);
 36	  if (part === 'legL' || part === 'legR') {
 37	    const f = part === 'legL' ? phase : phase + Math.PI;
 38	    const sw = Math.max(0, Math.cos(f - 0.35)), sr = Math.max(0, Math.cos(f + 0.45));   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
 39	    const knee = A * 2 * sw * sw + (A >= 0.01 ? 0.06 : 0);
 40	    return { root: A * Math.sin(f) + lerp(0.12 * A, 0.22, run), joint: -lerp(knee, 0.38 + 1.5 * sr * sr, run) };
 41	  }
 42	  const f = part === 'armL' ? phase + Math.PI : phase;
 43	  return { root: A * (0.65 + run * 0.5) * Math.sin(f) - 0.05, joint: 0.16 + run * 1.25 + A * 0.35 * Math.max(0, Math.sin(f)) };
 44	}
 45	import { CONFIG } from '../../config';
 46	import { rng } from '../math';
 47	import type { PersonKind } from './gait';
 48	
 49	/* =====================================================================
 50	   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
 51	   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
 52	   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
 53	   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
 54	   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
 55	   ===================================================================== */
 56	export const PP_FLAG = { hat: 1, pack: 2, photo: 4 } as const;
 57	export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }
 58	
 59	/* Xáo trộn Fisher–Yates bằng bộ sinh r */
 60	function ppShuffle<T>(a: T[], r: () => number): T[] {
 61	  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
 62	  return a;
 63	}
 64	
 65	export function ppAssignKinds(n: number, seed: number, opts?: { run?: boolean }): PersonInfo[] {
 66	  const P = CONFIG.people, M = P.mix, r = rng(seed), [s0, s1] = P.adultScale;
 67	  const out: PersonInfo[] = Array.from({ length: n }, () => ({ kind: 'walk' as PersonKind, scale: s0 + r() * (s1 - s0), flags: 0, phase: r() * Math.PI * 2, follow: -1 }));
 68	  // người đi cùng: chọn chỉ số i ≥ 1 sao cho i − 1 và i + 1 không cũng là người đi cùng (người dẫn không đi cùng ai)
 69	  const comp = new Set<number>(), nComp = Math.round(n * M.companion);
 70	  for (const i of ppShuffle(Array.from({ length: Math.max(0, n - 1) }, (_, k) => k + 1), r)) {
 71	    if (comp.size >= nComp) break;
 72	    if (!comp.has(i - 1) && !comp.has(i + 1)) comp.add(i);
 73	  }
 74	  const compList = [...comp].sort((a, b) => a - b);
 75	  for (const i of compList) out[i].follow = i - 1;
 76	  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
 77	  // người đứng và người chạy: lấy từ những người không đi cùng và không dẫn ai
 78	  const free = ppShuffle(out.map((_, i) => i).filter((i) => !comp.has(i) && !comp.has(i + 1)), r);
 79	  const nStand = Math.min(free.length, Math.round(n * M.stand)), nRun = opts?.run === false ? 0 : Math.min(free.length - nStand, Math.round(n * M.run));
 80	  const stand = free.slice(0, nStand);
 81	  for (const i of stand) out[i].kind = 'stand';
 82	  for (const i of free.slice(nStand, nStand + nRun)) out[i].kind = 'run';
 83	  // cờ: nón lá, ba lô trên mọi người; chụp ảnh trong số người đứng
 84	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
 85	  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
 86	  for (const i of ppShuffle(stand.slice(), r).slice(0, Math.round(stand.length * M.photo))) out[i].flags |= PP_FLAG.photo;
 87	  return out;
 88	}
