169	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
170	import { CONFIG } from '../../config';
171	
172	/* =====================================================================
173	   HÌNH HỌC NGƯỜI ĐI BỘ — một hình gộp cho mọi kiểu người (spec G5, G8): thân, đầu, tóc, hai tay (bắp tay áo cộc + cẳng tay),
174	   hai chân (đùi + ống quần + giày), nón lá, ba lô. Theo personGeo của bản dựng thử, bớt cạnh để ≤ CONFIG.people.maxVerts đỉnh.
175	   Mét, tỉ lệ 1: cao ≈ 1,65 m (≈ 1,79 m tính chóp nón), mặt hướng +X, rộng theo Z, chân chạm y = 0. Có index, không uv.
176	   Thuộc tính đỉnh (shader ở material.ts đọc):
177	   - aPart: 0 thân/đầu/tóc, 1 chân trái (−Z, vì mặt hướng +X), 2 chân phải (+Z), 3 tay trái, 4 tay phải, 5 nón lá, 6 ba lô (5, 6 bật theo cờ instance)
178	   - aSeg: 0 đoạn trên, 1 đoạn dưới khớp (quay thêm quanh aPivot2); aPivot: cao độ hông / vai; aPivot2: cao độ gối / khuỷu
179	   - aMask: 0 màu cố định aFix, 1 áo (instanceColor), 2 quần (aPants); aFix: màu cố định tuyến tính (da, tóc, giày, nón, ba lô)
180	   ===================================================================== */
181	export const PP_HIP = 0.86, PP_KNEE = 0.46, PP_SHOULDER = 1.37, PP_ELBOW = 1.1;   // m — cao độ khớp ở tỉ lệ 1
182	export enum PpPart { Body = 0, LegL = 1, LegR = 2, ArmL = 3, ArmR = 4, Hat = 5, Pack = 6 }
183	export enum PpMask { Fixed = 0, Shirt = 1, Pants = 2 }
184	
185	const C = CONFIG.people.palette;
186	const cap = (r: number, l: number) => new THREE.CapsuleGeometry(r, l, 2, 6);   // tay chân: 6 cạnh, nắp 2 đoạn
187	
188	/* Gắn thuộc tính khớp và màu cho một bộ phận; bỏ uv để mọi phần gộp được */
189	function ppTag(g: THREE.BufferGeometry, part: PpPart, pivot: number, fix: number, mask: PpMask, seg = 0, pivot2 = 0): THREE.BufferGeometry {
190	  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
191	  const n = g.getAttribute('position').count, col = new THREE.Color(fix), F = new Float32Array(n * 3);
192	  for (let i = 0; i < n; i++) { F[i * 3] = col.r; F[i * 3 + 1] = col.g; F[i * 3 + 2] = col.b; }
193	  const fill = (v: number) => new THREE.BufferAttribute(new Float32Array(n).fill(v), 1);
194	  g.setAttribute('aPart', fill(part)); g.setAttribute('aSeg', fill(seg)); g.setAttribute('aPivot', fill(pivot)); g.setAttribute('aPivot2', fill(pivot2));
195	  g.setAttribute('aMask', fill(mask)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
196	  return g;
197	}
