199	/* Dựng mới mỗi lần gọi (không cache): bên gọi giữ một bản dùng chung cho mọi hệ người nếu muốn */
200	export function ppBuildGeometry(): THREE.BufferGeometry {
201	  const parts = [
202	    ppTag(cap(0.15, 0.3).scale(0.78, 1, 1.18).translate(0, 1.12, 0), PpPart.Body, 0, C.skin, PpMask.Shirt),                     // thân (áo)
203	    ppTag(new THREE.SphereGeometry(0.115, 8, 6).translate(0, 1.54, 0), PpPart.Body, 0, C.skin, PpMask.Fixed),                    // đầu
204	    ppTag(new THREE.SphereGeometry(0.123, 8, 4, 0, Math.PI * 2, 0, 1.75).translate(-0.018, 1.553, 0), PpPart.Body, 0, C.hair, PpMask.Fixed),   // tóc (chỏm cầu, lệch ra sau)
205	    ppTag(new THREE.ConeGeometry(0.31, 0.17, 10).translate(0, 1.7, 0), PpPart.Hat, 0, C.hat, PpMask.Fixed),                      // nón lá
206	    ppTag(new THREE.BoxGeometry(0.13, 0.32, 0.25).translate(-0.18, 1.17, 0), PpPart.Pack, 0, C.pack, PpMask.Fixed)               // ba lô sau lưng (−X)
207	  ];
208	  for (const [side, leg, arm] of [[-1, PpPart.LegL, PpPart.ArmL], [1, PpPart.LegR, PpPart.ArmR]] as [number, PpPart, PpPart][]) {
209	    parts.push(ppTag(cap(0.072, 0.28).translate(0, 0.66, side * 0.085), leg, PP_HIP, C.skin, PpMask.Pants));                                    // đùi
210	    parts.push(ppTag(cap(0.058, 0.3).translate(0, 0.25, side * 0.085), leg, PP_HIP, C.skin, PpMask.Pants, 1, PP_KNEE));                          // ống chân
211	    parts.push(ppTag(new THREE.BoxGeometry(0.23, 0.07, 0.095).translate(0.045, 0.035, side * 0.085), leg, PP_HIP, C.shoe, PpMask.Fixed, 1, PP_KNEE));   // giày, mũi về +X
212	    parts.push(ppTag(cap(0.05, 0.18).translate(0, 1.235, side * 0.225), arm, PP_SHOULDER, C.skin, PpMask.Shirt));                                // bắp tay (áo cộc tay)
213	    parts.push(ppTag(cap(0.042, 0.2).translate(0, 0.96, side * 0.225), arm, PP_SHOULDER, C.skin, PpMask.Fixed, 1, PP_ELBOW));                    // cẳng tay
214	  }
215	  const g = mergeGeometries(parts);
216	  parts.forEach((p) => p.dispose());
217	  return g;
218	}
