  assert.deepEqual([...new Set(part)].sort(), [0, 1, 2, 3, 4, 5, 6]);
  for (let i = 0; i < n; i++) {
    assert.ok(seg[i] === 0 || seg[i] === 1, `aSeg ${seg[i]}`);
    if (seg[i] === 1) assert.ok(part[i] >= 1 && part[i] <= 4, `aSeg = 1 ở aPart ${part[i]}`);
