  ['sw', 'swOverview'], ['sw', 'swFront'], ['sw', 'swBase'], ['sw', 'swFromTTL'], ['sw', 'swNight'], ['sw', 'swTop'],
  // Ngồi cabin (GĐ5): camera gắn cabin, không thêm mesh
  ['sw', 'swRide'],
