 101	/* Còn đang hâm nền bộ đèn không (quality.update bỏ khung dài do biên dịch khỏi trung bình). Chế độ khác 'bg' không bao giờ hâm */
 102	export const lightsWarming = () => lightState.mode === 'bg' && !warmDone;
